import * as THREE from './assets/three.module.js';
const canvas=document.querySelector('#sculpture');let paused=document.body.classList.contains('paused'),onscreen=false,raf=0,t=0,mouse={x:0,y:0};
try{
const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,50);camera.position.set(0,0,7.5);const group=new THREE.Group();scene.add(group);
const material=new THREE.ShaderMaterial({vertexShader:`varying vec3 vN;varying vec3 vP;varying vec3 localP;void main(){localP=position;vN=normalize(normalMatrix*normal);vec4 p=modelViewMatrix*vec4(position,1.);vP=p.xyz;gl_Position=projectionMatrix*p;}`,fragmentShader:`varying vec3 vN;varying vec3 vP;varying vec3 localP;void main(){vec3 n=normalize(vN);vec3 v=normalize(-vP);float f=pow(1.-max(dot(n,v),0.),2.);vec3 blue=vec3(.035,.16,.55);vec3 cyan=vec3(.08,.68,.85);vec3 pink=vec3(.9,.16,.46);vec3 peach=vec3(1.,.65,.36);float band=sin(localP.y*1.8+localP.x*.7+n.x*2.);vec3 base=mix(blue,cyan,smoothstep(-1.,.1,band));base=mix(base,pink,smoothstep(.05,.7,band));base=mix(base,peach,smoothstep(.65,1.,band));vec3 light=normalize(vec3(-2.,3.,4.));float diffuse=max(dot(n,light),0.);float spec=pow(max(dot(reflect(-light,n),v),0.),70.);float strip=pow(max(dot(n,normalize(vec3(.5,1.,2.))),0.),16.);float edge=pow(max(dot(n,normalize(vec3(-1.,-.2,1.))),0.),32.);vec3 color=base*(.22+.72*diffuse)+vec3(.65,.8,1.)*spec*.9+vec3(1.,.94,.85)*strip*.35+vec3(.18,.45,1.)*edge*.6+f*vec3(.1,.3,.65)*.35;gl_FragColor=vec4(color,1.);}`});
const knot=new THREE.Mesh(new THREE.TorusKnotGeometry(1.13,.38,256,48,2,3),material);knot.scale.setScalar(.88);knot.rotation.set(.45,.15,-.4);group.add(knot);
const orbit=new THREE.Mesh(new THREE.TorusGeometry(2.18,.009,8,180),new THREE.MeshBasicMaterial({color:0x5c849f,transparent:true,opacity:.3}));orbit.rotation.set(1.12,.28,.2);group.add(orbit);const satellite=new THREE.Mesh(new THREE.IcosahedronGeometry(.12,2),new THREE.MeshNormalMaterial());scene.add(satellite);
function render(){knot.rotation.y=.15+t*.22+mouse.x*.5;knot.rotation.x=.45+Math.sin(t*.3)*.16+mouse.y*.2;group.position.y=Math.sin(t*.65)*.08;group.rotation.z=Math.sin(t*.25)*.07;orbit.rotation.z=t*.08;satellite.position.set(Math.cos(t*.4)*2.35,Math.sin(t*.4)*1.2,Math.sin(t*.4)*.6);renderer.render(scene,camera)}
function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();render()}new ResizeObserver(resize).observe(canvas);
let last=0;function tick(now){raf=0;if(paused||!onscreen||document.hidden)return;t+=Math.min((now-last)/1000,.04);last=now;render();raf=requestAnimationFrame(tick)}function start(){if(!raf&&!paused&&onscreen&&!document.hidden){last=performance.now();raf=requestAnimationFrame(tick)}}
addEventListener('motionchange',e=>{paused=e.detail.paused;if(paused){cancelAnimationFrame(raf);raf=0;render()}else start()});document.addEventListener('visibilitychange',start);new IntersectionObserver(e=>{onscreen=e[0].isIntersecting;start()}).observe(canvas);canvas.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width-.5;mouse.y=(e.clientY-r.top)/r.height-.5});canvas.addEventListener('pointerleave',()=>{mouse.x=0;mouse.y=0});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);canvas.parentElement.classList.remove('webgl-ready')});resize();canvas.parentElement.classList.add('webgl-ready');
}catch(error){console.warn('3D rendering unavailable; using static artwork.');}

